mapper.select:
SELECT c.*, p.id AS 'project.id', p.name AS 'project.name', p.short_name AS 'project.shortName', p.serial_number AS 'project.serialNumber' FROM contract_change AS c INNER JOIN contract_project as p on c.project_id = p.id and p.bool_delete_enum = 0
inner join ( (select id from contract_change where bool_delete_enum = 0 and user_id = #{userId}) union ( select cc.id from contract_change as cc inner join ( (select project_id from sys_project_user_link where bool_delete_enum = 0 and user_id = #{userId}) union (select id as project_id from contract_project where bool_delete_enum = 0 and user_id = #{userId}) ) as pids on cc.project_id = pids.project_id where cc.bool_delete_enum = 0 ) ) as id_list on c.id = id_list.id
inner join ( select id as project_id from contract_project where bool_delete_enum = 0 and (name like concat('%',#{name},'%') or short_name like concat('%',#{name},'%')) ) as pids on p.id = pids.project_id
WHERE c.bool_delete_enum = 0
and type in (1,2)
and c.project_id = #{projectId}
and DATE_FORMAT(c.change_date,'%Y') = #{year}
and c.user_name like concat('%',#{userName},'%')
and c.auditor_name like concat('%',#{auditorName},'%')
and c.type = #{type}
and c.audit_status = #{auditStatus}
order by c.audit_status , c.id desc
